static void whpx_set_kernel_irqchip ( Object * obj , Visitor * v , const char * name , void * opaque , Error * * errp ) { struct whpx_state * whpx = & whpx_global ; OnOffSplit mode ; switch ( mode ) { case ON_OFF_SPLIT_ON : whpx -> kernel_irqchip_allowed = true ; whpx -> kernel_irqchip_required = true ; break ; case ON_OFF_SPLIT_OFF : whpx -> kernel_irqchip_allowed = false ; whpx -> kernel_irqchip_required = false ; break ; case ON_OFF_SPLIT_SPLIT : error_setg ( errp , "WHPX: split irqchip currently not supported" ) ; error_append_hint ( errp , "Try without kernel-irqchip or with kernel-irqchip=on|off" ) ; break ; default : abort ( ) ; } } 